(() => {
  'use strict';
  const {drugs,categories}=MED_DATA, L=MED_LOGIC;
  const $=s=>document.querySelector(s), KEY='care-medicine-52-v1';
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let storageIssue='', saved={};
  try {saved=JSON.parse(localStorage.getItem(KEY)||'{}');if(!saved||typeof saved!=='object')saved={};}catch{storageIssue='保存された記録を読み込めません。この画面を閉じる前にブラウザの保存設定を確認してください。';}
  const prefs={sound:false,volume:35,dark:matchMedia('(prefers-color-scheme: dark)').matches,name:'brand',...saved.prefs};
  const progress={};
  for(const d of drugs){const p=saved.progress?.[d.id];if(p&&Number.isFinite(p.attempts)&&p.attempts>=0)progress[d.id]={...L.fresh(),...p,skills:{...L.fresh().skills,...p.skills}};}
  let session=null, audio=null, listQuery='', listCategory='', observation='', setupCategory='', setupMode='category', setupDifficulty=2;
  const names={category:'分類を覚える',action:'作用を覚える',care:'観察ポイント',recall:'完全暗記'};
  const levels=['未学習','見たことがある','分類がわかる','作用がわかる','観察までわかる','完全習得'];
  const displayName=d=>prefs.name==='brand'&&d.brandNames.length?d.brandNames[0]:d.genericName;
  const safety='このアプリは介護職員の学習を目的としたものです。薬の投与、中止、増減などを自己判断するためのものではありません。利用者の異常や体調変化を認めた場合は、看護師・医師などへ報告してください。';
  function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:1,prefs,progress}));}catch{storageIssue='記録を保存できません。ブラウザの保存制限や空き容量を確認してください。この画面内では学習を続けられます。';}showStorage();}
  function showStorage(){const e=$('#storage-warning');e.hidden=!storageIssue;e.textContent=storageIssue;}
  function applyPrefs(){document.body.classList.toggle('dark',prefs.dark);$('#sound-toggle').textContent=prefs.sound?'♫':'♪';$('#sound-toggle').setAttribute('aria-pressed',String(prefs.sound));$('#sound-toggle').setAttribute('aria-label',prefs.sound?'効果音をオフにする':'効果音をオンにする');$('#sound-toggle').title=prefs.sound?'効果音：オン':'効果音：オフ';$('#sound-setting').checked=prefs.sound;$('#dark-setting').checked=prefs.dark;$('#volume').value=prefs.volume;$('#name-setting').value=prefs.name;}
  function unlock(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(Audio&&!audio)audio=new Audio();if(audio?.state==='suspended')audio.resume().catch(()=>{});}catch{}}
  function tone(type){if(!prefs.sound||!prefs.volume)return;unlock();if(!audio)return;const notes=type==='wrong'?[220,174]:type==='done'?[523,659,784,1046]:[659,880];try{notes.forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.13;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.12*prefs.volume/100,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+.18);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.2);o.onended=()=>{o.disconnect();g.disconnect();};});}catch{}}
  function go(hash){if(location.hash==='#'+hash)render();else location.hash=hash;}
  function mastery(){const mastered=drugs.filter(d=>progress[d.id]?.level===5).length, learning=drugs.filter(d=>progress[d.id]?.attempts&&progress[d.id].level<5).length;return{mastered,learning,unseen:52-mastered-learning};}
  function bar(m){return `<div class="progress" aria-label="習得 ${m.mastered}、学習中 ${m.learning}、未学習 ${m.unseen}"><span style="width:${m.mastered/52*100}%"></span><span class="learning" style="width:${m.learning/52*100}%"></span></div><div class="legend"><span>習得 ${m.mastered}</span><span>学習中 ${m.learning}</span><span>未学習 ${m.unseen}</span></div>`;}
  function home(){const plan=L.today(drugs,progress),m=mastery();return `<div class="eyebrow">毎日の学び</div><h1>今日の学習</h1><div class="dashboard"><div><section><div class="metrics"><div class="metric"><span>新しく覚える</span><strong>${plan.unseen.length}</strong></div><div class="metric"><span>復習</span><strong>${plan.due.length}</strong></div><div class="metric"><span>苦手</span><strong>${plan.difficult.length}</strong></div></div><button class="primary wide" data-do="today">${plan.all.length?plan.all.length+'項目を学ぶ':'追加で5項目を復習'}</button></section><section><div class="section-heading"><h2>習得状況</h2><strong>${m.mastered} / 52</strong></div>${bar(m)}</section><section><h2>重点学習</h2><button class="secondary wide" data-do="important">重要薬の観察ポイント</button></section></div><div><section><h2>学習モード</h2>${Object.entries(names).map(([k,n],i)=>`<button class="mode-row" data-mode="${k}"><span><b class="step">${String(i+1).padStart(2,'0')}</b>${n}</span><small>${k==='recall'?'○ △ ×':'クイズ'}</small></button>`).join('')}</section></div></div><section><div class="section-heading"><h2>分類から学ぶ</h2><span class="muted">15分類</span></div><div class="category-grid">${categories.map((c,i)=>`<button data-category="${i}">${c}<small>${drugs.filter(d=>d.category===c).length}項目</small></button>`).join('')}</div></section>`;}
  function setup(){return `<div class="study"><button class="back" data-do="home">‹ ホーム</button><h1>${names[setupMode]}</h1><div class="filters"><label>分類<select id="study-category"><option value="">すべての分類</option>${categories.map(c=>`<option ${setupCategory===c?'selected':''}>${c}</option>`).join('')}</select></label><label>学習量<select id="study-count"><option value="5">5項目</option><option value="10">10項目</option></select></label></div>${setupMode!=='recall'?`<label>難易度<select id="difficulty"><option value="2" ${setupDifficulty===2?'selected':''}>レベル1：2択</option><option value="4" ${setupDifficulty===4?'selected':''}>レベル2：4択</option><option value="hint" ${setupDifficulty==='hint'?'selected':''}>レベル3：ヒントで思い出す</option></select></label>`:'<p class="muted">薬名から分類・作用・観察ポイントを思い出します。</p>'}<button class="primary wide" style="margin-top:24px" data-do="begin">学習を始める</button></div>`;}
  function start(items,mode='category',difficulty=2){unlock();session={queue:items.map(d=>({id:d.id,mode})),index:0,results:[],options:null,answered:false,revealed:false,hint:false,retried:new Set(),difficulty,finished:false};go('study');}
  function current(){return session?.queue[session.index];}
  function study(){if(!session)return setup();if(session.finished)return finish();const item=current(),d=drugs.find(x=>x.id===item.id);const recall=item.mode==='recall',hintMode=session.difficulty==='hint';if(!recall&&!hintMode&&!session.options)session.options=L.choices(d,item.mode,drugs,Number(session.difficulty));return `<div class="study"><div class="session-actions"><button class="back" data-do="quit">‹ 学習を終了</button><small>${session.index+1} / ${session.queue.length}問</small></div><div class="eyebrow">${names[item.mode]}${item.retry?' ・ もう一度':''}</div><div class="progress"><span style="width:${session.index/session.queue.length*100}%"></span></div><h1>${esc(displayName(d))}</h1><div class="section-heading"><span class="muted">${displayName(d)!==d.genericName?'一般名：'+esc(d.genericName):d.brandNames.length?'商品名：'+esc(d.brandNames.join('／')):''}</span><button class="read-button" data-read="${d.id}">読み上げ</button></div>${recall||hintMode?recallUI(d,item.mode):quizUI(d,item.mode)}</div>`;}
  function quizUI(d,mode){const correct=L.answer(d,mode);const question=mode==='category'?'どの分類の薬でしょう？':mode==='action'?'主な作用はどれでしょう？':'この教材で結びつける観察ポイントは？';return `<p class="question">${question}</p><div class="answers">${session.options.map((o,i)=>`<button class="answer ${session.answered?(o===correct?'correct':session.selected===i?'wrong':''):''}" data-answer="${i}" ${session.answered?'disabled':''}><span class="choice-letter">${session.answered&&o===correct?'✓':String.fromCharCode(65+i)}</span><span>${esc(o)}</span></button>`).join('')}</div>${session.answered?`<div class="feedback ${session.correct?'':'wrong'}" role="status"><h2>${session.correct?'正解':'もう一度、覚えよう'}</h2><p><strong>${esc(correct)}</strong></p><p>${esc(d.note)}</p>${mode==='care'?'<small>ここにない症状も観察・報告の対象です。</small>':''}</div><button class="primary wide" data-do="next">${session.index+1===session.queue.length?'結果を見る':'次の問題へ'}</button>`:''}`;}
  function facts(d){return `<dl class="detail-rows"><div><dt>分類</dt><dd>${esc(d.subCategory)}</dd></div><div><dt>一言でいうと</dt><dd>${esc(d.shortAction)}</dd></div><div><dt>介護士が見るところ</dt><dd class="care-tags">${d.carePoints.map(p=>`<span>${esc(p)}</span>`).join('')}</dd></div></dl>`;}
  function recallUI(d,mode){return `${session.revealed?`${facts(d)}<p class="muted">${esc(d.note)}</p><h2>どのくらい覚えた？</h2><div class="ratings"><button data-rating="2"><b>○</b>覚えた</button><button data-rating="1"><b>△</b>あやしい</button><button data-rating="0"><b>×</b>わからない</button></div>`:`<div class="recall-hidden"><p class="muted">${mode==='recall'?'分類・作用・観察ポイントを思い出す':names[mode]+'：答えを思い出す'}</p></div>${session.difficulty==='hint'?`<button class="secondary wide" data-do="hint">${session.hint?esc(L.answer(d,mode).slice(0,3))+'…':'ヒントを見る'}</button>`:''}<button class="primary wide" style="margin-top:12px" data-do="reveal">答えを見る</button>`}`;}
  function record(rating){const item=current();progress[item.id]=L.update(progress[item.id],item.mode,rating);session.results.push({id:item.id,rating,retry:!!item.retry});if(rating<2&&!session.retried.has(item.id)){session.retried.add(item.id);const retry={...item,retry:true};session.queue.splice(Math.min(session.index+4,session.queue.length),0,retry);if(session.index+4<session.queue.length-1)session.queue.push({...retry});}persist();tone(rating===2?'correct':'wrong');}
  function next(){session.index++;session.options=null;session.answered=false;session.revealed=false;session.hint=false;if(session.index>=session.queue.length){session.finished=true;tone('done');}render();}
  function finish(){const first=session.results.filter(r=>!r.retry),correct=first.filter(r=>r.rating===2).length;return `<div class="study"><div class="eyebrow">学習完了</div><h1>おつかれさまでした</h1><div class="score">${correct}<span class="muted" style="font-size:24px"> / ${first.length}</span></div><p>最初の回答で正解・「覚えた」になった項目</p><p class="muted">復習を含めて ${session.results.length} 回取り組みました。</p><ul class="finish-list">${first.map(r=>{const d=drugs.find(d=>d.id===r.id);return `<li><a href="#drug/${d.id}"><span>${esc(displayName(d))}</span><span class="result-label">${['× 復習','△ あやしい','○ 覚えた'][r.rating]}</span></a></li>`;}).join('')}</ul><button class="primary wide" data-do="home">ホームへ</button></div>`;}
  function normalized(s){return s.normalize('NFKC').toLowerCase().replace(/[ぁ-ゖ]/g,c=>String.fromCharCode(c.charCodeAt(0)+0x60));}
  function filtered(weakOnly){const q=normalized(listQuery);return drugs.filter(d=>(!weakOnly||L.weak(progress[d.id]))&&(!listCategory||d.category===listCategory)&&(!observation||d.carePoints.some(p=>p.includes(observation)))&&(!q||normalized([d.genericName,...d.brandNames,d.category,d.subCategory,d.shortAction,...d.carePoints].join(' ')).includes(q)));}
  function drugRows(items){return items.length?items.map(d=>`<a href="#drug/${d.id}" class="drug-row"><span><strong>${esc(displayName(d))}</strong><small>${esc(displayName(d)!==d.genericName?d.genericName:d.brandNames.join('／'))}</small><small>${d.subCategory}</small></span><span class="badge">${levels[progress[d.id]?.level||0]}</span></a>`).join(''):'<div class="empty"><h2>該当する薬はありません</h2><p class="muted">検索語や絞り込みを変えてみてください。</p></div>';}
  function list(weakOnly=false){const items=filtered(weakOnly),allWeak=drugs.filter(d=>L.weak(progress[d.id]));return `<div class="eyebrow">${weakOnly?'繰り返して定着':'薬名と観察をつなぐ'}</div><h1>${weakOnly?'苦手な薬':'薬一覧'}</h1>${weakOnly&&!allWeak.length?'<div class="empty"><h2>苦手な薬はまだありません</h2><p class="muted">学習の回答に応じて、ここに集まります。</p><button class="primary" data-do="today">今日の学習へ</button></div>':`${weakOnly?'<button class="primary wide" data-do="weak-start">苦手を5項目復習する</button>':''}<label class="sr-only" for="search">薬名・商品名・分類・観察で検索</label><input id="search" type="search" placeholder="薬名・商品名・分類・観察で検索" value="${esc(listQuery)}"><div class="filters"><label>分類<select id="list-category"><option value="">すべて</option>${categories.map(c=>`<option ${c===listCategory?'selected':''}>${c}</option>`).join('')}</select></label><label>観察ポイント<select id="observation"><option value="">すべて</option>${['出血','低血糖','転倒','脱水','下痢','眠気','傾眠'].map(c=>`<option ${c===observation?'selected':''}>${c}</option>`).join('')}</select></label></div><p class="muted" id="result-count">${items.length}項目</p><div class="drug-list" id="drug-results">${drugRows(items)}</div>`}`;}
  function detail(id){const d=drugs.find(d=>d.id===id);if(!d)return '<h1>薬が見つかりません</h1><a href="#list">薬一覧へ</a>';const p=progress[id];return `<div class="study"><button class="back" data-do="list">‹ 薬一覧</button><div class="eyebrow">${d.category} ・ ${d.importance===5?'重要薬':'基本薬'}</div><h1>${esc(d.genericName)}</h1>${d.brandNames.length?`<p class="muted">商品名：${esc(d.brandNames.join('／'))}</p>`:''}<button class="read-button" data-read="${id}">読み上げ</button>${facts(d)}<h2>補足</h2><p>${esc(d.note)}</p><div class="stats-row"><span class="badge">${levels[p?.level||0]}</span><p class="muted">${p?.next?'次回復習：'+new Date(p.next).toLocaleDateString('ja-JP'):'まだ学習していません'}</p></div><div class="inline-actions"><button class="primary" data-single="${id}">暗記カードで学ぶ</button><a href="https://www.pmda.go.jp/PmdaSearch/iyakuSearch/" target="_blank" rel="noopener noreferrer">PMDAで添付文書を確認</a></div></div>`;}
  function stats(){const m=mastery(),ps=Object.values(progress),total=ps.reduce((a,p)=>a+p.attempts,0),right=ps.reduce((a,p)=>a+p.correct,0);return `<div class="eyebrow">積み重ねの記録</div><h1>学習記録</h1><div class="metrics"><div class="metric"><span>回答回数</span><strong>${total}</strong></div><div class="metric"><span>正解・覚えた</span><strong>${right}</strong></div><div class="metric"><span>習得率</span><strong>${Math.round(m.mastered/52*100)}<small>%</small></strong></div></div>${bar(m)}<p class="muted">「完全暗記」で「覚えた」を2回記録すると完全習得になります。選択問題と自己評価を含む記録です。</p><h2>分類ごとの習得</h2>${categories.map(c=>{const all=drugs.filter(d=>d.category===c),done=all.filter(d=>progress[d.id]?.level===5).length;return `<div class="stats-row"><div><span>${c}</span><strong>${done} / ${all.length}</strong></div><div class="progress"><span style="width:${done/all.length*100}%"></span></div></div>`;}).join('')}`;}
  function safetyPage(){return `<div class="safety-copy"><h1>学習目的・医療安全</h1><p>${safety}</p><h2>教材について</h2><p>指定された52項目を15分類で収録しています。「抗菌薬」「インスリン」「レボドパ配合剤」など、単一の製品ではない項目も含みます。</p><p>作用・観察ポイントは初学者向けの要約です。すべての効能や副作用を網羅せず、薬・剤形・併用薬・利用者の状態によって異なります。観察問題の他の選択肢にある症状も、報告が不要という意味ではありません。</p><p>教材は専門職による全項目の監修を受けていません。施設での正式な研修利用前には、看護師・薬剤師などによる確認を受けてください。</p><h2>参照情報</h2><p>内容の土台は提供された開発指示書です。以下は重要な注意点の確認に使った資料であり、全52項目の検証を示すものではありません。</p><ul><li><a href="https://www.pmda.go.jp/PmdaSearch/iyakuSearch/" target="_blank" rel="noopener noreferrer">PMDA 医療用医薬品 添付文書等情報検索</a></li><li><a href="https://www.info.pmda.go.jp/downfiles/ph/GUI/670605_3339004F1029_1_00G.pdf" target="_blank" rel="noopener noreferrer">エリキュース：患者向医薬品ガイド</a></li><li><a href="https://www.pmda.go.jp/files/000214495.pdf" target="_blank" rel="noopener noreferrer">酸化マグネシウム：適正使用に関するお願い</a></li></ul><p class="muted">作成日：2026年10月3日</p><h2>記録と音</h2><p>記録はこの端末のこのブラウザに保存されます。閲覧データの削除やプライベートブラウズの終了で消えることがあります。患者名などの個人情報は入力しません。</p><p>効果音は設定から切り替えられます。読み上げの声と対応状況は端末によって異なります。</p></div>`;}
  function render(){const path=location.hash.slice(1)||'home',page=path.split('/')[0];document.body.classList.toggle('studying',page==='study'&&!!session&&!session.finished);if(page!=='study')window.speechSynthesis?.cancel();const routes={home,setup,study,list:()=>list(false),weak:()=>list(true),stats,safety:safetyPage,drug:()=>detail(Number(path.split('/')[1]))};$('#main').innerHTML=(routes[page]||home)();document.querySelectorAll('.bottom-nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===(page==='drug'?'list':page)));document.title=(page==='study'?'学習中':page==='list'?'薬一覧':page==='stats'?'学習記録':'薬52種')+' | 介護士の学習ノート';window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
  function showSetup(mode,cat=''){setupMode=mode;setupCategory=cat;go('setup');}
  function speak(id){const d=drugs.find(d=>d.id===id);if(!window.speechSynthesis){alert('このブラウザでは読み上げを利用できません。');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(displayName(d));u.lang='ja-JP';u.rate=.85;u.volume=prefs.volume/100;speechSynthesis.speak(u);}
  document.addEventListener('click',e=>{
    const b=e.target.closest('button');if(!b)return;
    if(b.dataset.mode){showSetup(b.dataset.mode);return;}
    if(b.dataset.category!==undefined){showSetup('category',categories[Number(b.dataset.category)]);return;}
    if(b.dataset.single){start([drugs.find(d=>d.id===Number(b.dataset.single))],'recall');return;}
    if(b.dataset.read){speak(Number(b.dataset.read));return;}
    if(b.dataset.answer!==undefined&&session&&!session.answered){const i=Number(b.dataset.answer),d=drugs.find(d=>d.id===current().id);session.selected=i;session.correct=session.options[i]===L.answer(d,current().mode);session.answered=true;record(session.correct?2:0);render();return;}
    if(b.dataset.rating!==undefined&&session&&session.revealed&&!session.answered){session.answered=true;record(Number(b.dataset.rating));next();return;}
    switch(b.dataset.do){
      case 'home':session=null;go('home');break;
      case 'list':go('list');break;
      case 'today':{const plan=L.today(drugs,progress);const items=plan.all.length?plan.all:L.shuffle(drugs).slice(0,5);start(items);session.queue=session.queue.map(item=>{const p=progress[item.id];return {...item,mode:!p?.skills.category?'category':!p.skills.action?'action':!p.skills.care?'care':'recall'};});render();break;}
      case 'important':start(L.shuffle(drugs.filter(d=>d.importance===5)).slice(0,10),'care',4);break;
      case 'weak-start':start(L.shuffle(drugs.filter(d=>L.weak(progress[d.id]))).slice(0,5),'recall');break;
      case 'begin':{setupCategory=$('#study-category').value;setupDifficulty=$('#difficulty')?.value==='hint'?'hint':Number($('#difficulty')?.value||2);const items=L.shuffle(drugs.filter(d=>!setupCategory||d.category===setupCategory)).slice(0,Number($('#study-count').value));start(items,setupMode,setupDifficulty);break;}
      case 'reveal':session.revealed=true;render();break;
      case 'hint':session.hint=true;render();break;
      case 'next':if(session?.answered)next();break;
      case 'quit':if(confirm('ここまでの回答は保存されています。学習を終了しますか？')){session=null;go('home');}break;
    }
  });
  document.addEventListener('input',e=>{if(e.target.id==='search'){listQuery=e.target.value;refreshResults();}});
  function refreshResults(){const items=filtered(location.hash==='#weak');$('#drug-results').innerHTML=drugRows(items);$('#result-count').textContent=items.length+'項目';}
  document.addEventListener('change',e=>{if(e.target.id==='list-category'){listCategory=e.target.value;refreshResults();}if(e.target.id==='observation'){observation=e.target.value;refreshResults();}});
  $('#settings-button').onclick=()=>{applyPrefs();$('#settings').showModal();};
  $('#sound-toggle').onclick=()=>{prefs.sound=!prefs.sound;applyPrefs();persist();tone('correct');};
  $('#sound-setting').onchange=e=>{prefs.sound=e.target.checked;applyPrefs();persist();tone('correct');};
  $('#dark-setting').onchange=e=>{prefs.dark=e.target.checked;applyPrefs();persist();};
  $('#volume').oninput=e=>{prefs.volume=Number(e.target.value);persist();};
  $('#name-setting').onchange=e=>{prefs.name=e.target.value;persist();render();};
  $('#test-sound').onclick=()=>{prefs.sound=true;applyPrefs();persist();tone('correct');};
  $('#export-data').onclick=()=>{const payload={format:'care-medicine-52',version:1,exportedAt:new Date().toISOString(),prefs,progress};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='薬52種-学習データ.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
  $('#import-data').onclick=()=>$('#import-file').click();
  $('#import-file').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const incoming=JSON.parse(await file.text());if(incoming.format!=='care-medicine-52'||!incoming.progress)throw new Error('形式が違います');for(const d of drugs){const p=incoming.progress[d.id];if(p&&Number.isFinite(p.attempts))progress[d.id]={...L.fresh(),...p,skills:{...L.fresh().skills,...p.skills}};}if(incoming.prefs&&typeof incoming.prefs==='object')Object.assign(prefs,incoming.prefs);persist();applyPrefs();$('#settings').close();render();alert('学習データを読み込みました。');}catch(err){alert('読み込みに失敗しました。JSONファイルを確認してください。');}e.target.value='';};
  window.addEventListener('hashchange',render);
  applyPrefs();showStorage();render();
})();
